package com.joyhsin.hotspot;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.nio.file.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class SceneControllerTest {static Path dir;static{try{dir=Files.createTempDirectory("hotspot-test");}catch(Exception e){throw new RuntimeException(e);}} @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("hotspot.data-directory",()->dir.toString());}@Autowired MockMvc mvc;
 @Test void sampleDraftPublishFlow() throws Exception {String body=mvc.perform(post("/api/scenes/sample")).andExpect(status().isCreated()).andExpect(jsonPath("$.publishedHotspots.length()").value(4)).andReturn().getResponse().getContentAsString();String id=new com.fasterxml.jackson.databind.ObjectMapper().readTree(body).get("id").asText();mvc.perform(put("/api/scenes/"+id+"/draft").contentType(MediaType.APPLICATION_JSON).content("{\"hotspots\":[]}" )).andExpect(status().isOk()).andExpect(jsonPath("$.draftHotspots.length()").value(0));mvc.perform(post("/api/scenes/"+id+"/publish")).andExpect(status().isOk()).andExpect(jsonPath("$.publishedHotspots.length()").value(0));}
 @Test void rejectsFakeImage() throws Exception {mvc.perform(multipart("/api/scenes").file("image","not-an-image".getBytes()).param("name","bad")).andExpect(status().isBadRequest());}}
